import{z as o,x as s,o as e,c as d,q as t,j as r,D as A,d as B,s as l,S as i,b as a}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"在线学习","description":"","frontmatter":{"title":"在线学习","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/fml-online-learning.md","filePath":"quant/fml-online-learning.md","lastUpdated":1791063341000}'),m={name:"quant/fml-online-learning.md"};function C(p,E,D,F,f,u){const n=s("Mermaid");return e(),d("div",null,[E[2]||(E[2]=t('<h1 id="在线学习" tabindex="-1">在线学习 <a class="header-anchor" href="#在线学习" aria-label="Permalink to &quot;在线学习&quot;">​</a></h1><div class="epigraph"><p>递归辨识的收敛不看步长多小，而看激励是否持续；市场不保证持续激励，在线更新因此不是免费的自适应。</p><footer>—— 据 Ljung, IEEE Transactions on Automatic Control, 1977；Ljung and Söderström, Theory and Practice of Recursive Identification, 1983 整理</footer></div><p><a href="/quant/fml-explainability-deep">上一课</a>给模型配了能被质询的语言，静态模型由此上线。缺口：市场在动，静态模型的系数是某个历史窗口的化石——什么时候允许模型边跑边学、学多快、出事怎么退，是本课的问题。<a href="/quant/bocpd-online-changepoint">BOCPD 在线变点检测</a>已给在线变点信念的滤波器，<a href="/quant/kalman-spread">Kalman 价差</a>一类状态空间已给参数漂移的最小模型。本课把在线学习当运维对象写：更新方式、步长账、遗忘与重置、验收。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>静态部署与每日全量重训之间有一段光谱：warm start 用新数据微调旧模型，快但继承旧结构的偏；流式更新（SGD、递归最小二乘）逐条或逐批改系数，跟得快，却把「样本顺序」变成新的超参；状态空间把参数当状态，漂移显式建模，代价是结构受限。三个坑横在这段光谱上。步长与漂移速度错配：太快，每条微观噪声都写进系数；太慢，体制已换而系数还在原地。遗忘不对称：旧体制回归时，被遗忘的参数要从头再学——灾难性遗忘在金融的形态，是回归的均值回复策略突然不会做。顺序偏差：流式模型是训练顺序的函数，同一份数据换个顺序就是另一个模型；回测与实盘的更新顺序若不同，上线的不是被验收的那个模型。</p><p><span class="marginnote">warm start 翻译成大白话：不从头训练，拿旧模型的参数当起点继续练——像接力赛交接棒，快，但上一棒跑歪的方向也会被继承。流式更新则是边跑边改答案：每来一条新数据就把系数挪一小步。</span></p><p><span class="marginnote">顺序偏差可以类比做菜的下料顺序：同样的食材，先放盐和后放盐是两道菜。流式模型就是「下料顺序」的函数——回测若打乱顺序训练、实盘按市场顺序更新，端上桌的就不是验收过的那道菜。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>步长账。遗忘因子 \\(\\lambda\\) 对应有效样本窗 \\(N_{\\mathrm{eff}}=1/(1-\\lambda)\\)，恒定学习率 \\(\\eta\\) 亦同量级；按信号半衰期选窗——衰减快则窗短，慢则窗长，标定窗长的尝试计入 \\(N\\) 台账。重置规则预写成状态机：变点信念（<a href="/quant/bocpd-online-changepoint">BOCPD</a> 或 CUSUM）穿带，触发参数重置或退回全量重训；分流逻辑归下一课，这里只接接口。验收只认滤波口径：\\(t\\) 时刻的预测必须在用 \\(t\\) 及之前数据完成更新之后做出，用了未来更新再回头预测的平滑口径是泄漏；上线后模型按日做版本快照，与冻结的离线基线影子对照。</p>',9)),(e(),r(i,null,{default:A(()=>[l(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20NEW%5B%22%E6%96%B0%E6%95%B0%E6%8D%AE%EF%BC%88%E5%B8%82%E5%9C%BA%E9%A1%BA%E5%BA%8F%EF%BC%89%22%5D%20--%3E%20UPD%5B%22%E6%9B%B4%E6%96%B0%EF%BC%9Awarm%20start%20%E6%88%96%E6%B5%81%E5%BC%8F%E6%88%96%E7%8A%B6%E6%80%81%E7%A9%BA%E9%97%B4%22%5D%0A%20%20UPD%20--%3E%20STEP%5B%22%E6%AD%A5%E9%95%BF%E8%B4%A6%EF%BC%9A%E6%9C%89%E6%95%88%E7%AA%97%E5%AF%B9%E9%BD%90%E4%BF%A1%E5%8F%B7%E5%8D%8A%E8%A1%B0%E6%9C%9F%22%5D%0A%20%20STEP%20--%3E%20SNAP%5B%22%E7%89%88%E6%9C%AC%E5%BF%AB%E7%85%A7%EF%BC%9A%E6%8C%89%E6%97%A5%22%5D%0A%20%20SNAP%20--%3E%20SHA%5B%22%E5%BD%B1%E5%AD%90%E5%AF%B9%E7%85%A7%EF%BC%9A%E5%86%BB%E7%BB%93%E7%9A%84%E7%A6%BB%E7%BA%BF%E5%9F%BA%E7%BA%BF%22%5D%0A%20%20SHA%20--%3E%20CP%5B%22%E5%8F%98%E7%82%B9%E4%BF%A1%E5%BF%B5%E7%A9%BF%E5%B8%A6%EF%BC%9F%22%5D%0A%20%20CP%20--%3E%7C%22'%E6%98%AF'%22%7C%20RESET%5B%22%E9%87%8D%E7%BD%AE%E5%8F%82%E6%95%B0%E6%88%96%E5%9B%9E%E6%BB%9A%E5%85%A8%E9%87%8F%E9%87%8D%E8%AE%AD%22%5D%0A%20%20CP%20--%3E%7C%22'%E5%90%A6'%22%7C%20KEEP%5B%22%E7%BB%A7%E7%BB%AD%E5%9C%A8%E7%BA%BF%E6%9B%B4%E6%96%B0%22%5D%0A%20%20RESET%20--%3E%20STEP%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[B("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,[B("在线为什么不是免费的自适应：递归辨识的收敛条件是持续激励——数据要持续「问」到参数的各个方向；低波动横盘期市场不给激励，系数沿噪声方向缓慢漂移，参数动了不等于信号更新了。锚因此必要：在线正则（向冻结的先验收缩）把无激励期的漂移拴住，先验就是上次通过验收的那组系数。顺序偏差为什么实盘更大：实盘的更新顺序就是市场顺序，回测若在打乱顺序上调步长，调出的步长必然错——步长与窗长的标定必须在时间序上做，与"),a("a",{href:"/quant/fml-tscv-deep"},"时序交叉验证"),B("的切分纪律同源。遗忘不对称的缓解是结构性的：把「快变部分」（如当前波动）与「慢变部分」（如因子载荷）分给不同时间尺度的两个状态，慢变部分少遗忘，快变部分放开追。")],-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"数字实例：\\(\\lambda\\) 从 0.99 调到 0.999，看似只动小数点后一位，\\(N_{\\mathrm{eff}}\\) 却从约 100 个样本跳到 1000 个——日频下等于把记忆从一个季度拉长到约四年。窗比信号半衰期长太多，旧体制的样本就在系数里占了多数。")],-1)),(e(),r(i,null,{default:A(()=>[l(n,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20LR%0A%20%20D%5B%22%E6%96%B0%E6%95%B0%E6%8D%AE%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20Q%7B%22%E6%9C%89%E6%8C%81%E7%BB%AD%E6%BF%80%E5%8A%B1%EF%BC%9F%E6%B3%A2%E5%8A%A8%E6%88%96%E8%B6%8B%E5%8A%BF%E6%9C%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E6%98%AF%22%7C%20UPD%5B%22%E7%B3%BB%E6%95%B0%E6%9C%9D%E4%BF%A1%E5%8F%B7%E6%96%B9%E5%90%91%E6%9B%B4%E6%96%B0%22%5D%0A%20%20Q%20--%3E%7C%22%E5%90%A6%EF%BC%9A%E4%BD%8E%E6%B3%A2%E5%8A%A8%E6%A8%AA%E7%9B%98%22%7C%20DR%5B%22%E7%B3%BB%E6%95%B0%E6%B2%BF%E5%99%AA%E5%A3%B0%E6%96%B9%E5%90%91%E7%BC%93%E6%85%A2%E6%BC%82%E7%A7%BB%22%5D%0A%20%20DR%20--%3E%20ANCH%5B%22%E5%9C%A8%E7%BA%BF%E6%AD%A3%E5%88%99%EF%BC%9A%E5%90%91%E5%85%88%E9%AA%8C%E6%94%B6%E7%BC%A9%22%5D%0A%20%20ANCH%20--%3E%20FP%5B%22%E5%85%88%E9%AA%8C%EF%BC%9A%E4%B8%8A%E6%AC%A1%E9%80%9A%E8%BF%87%E9%AA%8C%E6%94%B6%E7%9A%84%E7%B3%BB%E6%95%B0%22%5D%0A%20%20UPD%20--%3E%20SNAP%5B%22%E6%8C%89%E6%97%A5%E7%89%88%E6%9C%AC%E5%BF%AB%E7%85%A7%22%5D%0A%20%20FP%20--%3E%20SNAP%0A%20%20SNAP%20--%3E%20SHA%5B%22%E4%B8%8E%E5%86%BB%E7%BB%93%E7%A6%BB%E7%BA%BF%E5%9F%BA%E7%BA%BF%E5%BD%B1%E5%AD%90%E5%AF%B9%E7%85%A7%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=t('<p><span class="marginnote">窗长对照：\\(\\lambda=0.99\\) 对应 \\(N_{\\mathrm{eff}}\\approx 100\\) 个样本。若信号半衰期约 60 个交易日，这个窗记住近一个半衰期的市场；窗再长，旧体制的样本就在系数里占了多数。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>Bandit 与强化学习对执行参数的在线优化是执行课程的对象，此处不展开。在线学习不替代漂移检测：它假设漂移可被步长吸收，哪些漂移该追、哪些该停机，分流逻辑归下一课。参数服务的分布式工程（参数服务器、增量特征回灌）不在本课粒度内，本课到「逐日批更新还是逐笔流式」为止。在线模型同样受审计约束：每次更新可复现（数据顺序、随机种子入账）是它进入生产的前置条件，标准与本课程审计一课一致。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>更新方式是光谱：warm start、流式、状态空间；选择标准是漂移速度与结构约束，不是先进性。</li><li>步长账按信号半衰期定有效窗；标定在时间序上做，计入 \\(N\\)。</li><li>无激励期系数沿噪声漂移，在线正则向已验收的先验收缩。</li><li>验收只认滤波口径，平滑是泄漏；版本按日快照与离线基线影子对照。</li><li>出处：Ljung, <em>IEEE TAC</em>, 1977；Ljung and Söderström, <em>Theory and Practice of Recursive Identification</em>, MIT Press, 1983；Adams and MacKay, 2007。</li></ul>',5))])}const P=o(m,[["render",C]]);export{c as __pageData,P as default};
